[Console]::OutputEncoding=New-Object Text.UTF8Encoding($false);[ordered]@{utc=[DateTime]::UtcNow.ToString('o');board_tool_processes=@(Get-CimInstance Win32_Process|Where-Object {$_.Name -match '^(hw_server|vivado|cs_server)(\.exe)?$' -or ($_.Name -eq 'python.exe' -and $_.CommandLine -like '*scalellm_windows_xdma.py*--rpc*')}|Select-Object ProcessId,ParentProcessId,Name,CreationDate,CommandLine);listener33121=@(Get-NetTCPConnection -State Listen -LocalPort 33121 -ErrorAction SilentlyContinue|Select-Object LocalPort,OwningProcess);pnp=@(Get-PnpDevice -PresentOnly|Where-Object {$_.InstanceId -like 'PCI\VEN_10EE*'}|Select-Object Status,FriendlyName,InstanceId,Problem)}|ConvertTo-Json -Depth 6 -Compress